mapper.update:
update pm_requirement
set status = #{status}, update_time = CURRENT_TIMESTAMP
where project_id = #{projectId}
  and requirement_id = #{requirementId}
  and is_deleted = 0

update pm_requirement
set current_version_id = #{versionId}, update_time = CURRENT_TIMESTAMP
where requirement_id = #{requirementId}

mapper.select:

and r.project_id = #{projectId}
and r.requirement_id = #{requirementId}
and exists (
    select 1 from pm_project_member access_member
    where access_member.project_id = r.project_id
      and access_member.user_id = #{userId}
)

select v.version_id, v.requirement_id, v.version_no, v.title, v.content,
       v.attachment_snapshot, v.created_by, v.create_time
from pm_requirement_version v
inner join pm_requirement r on r.requirement_id = v.requirement_id
where r.is_deleted = 0
  and r.project_id = #{projectId}
  and r.requirement_id = #{requirementId}
  and exists (
      select 1 from pm_project_member access_member
      where access_member.project_id = r.project_id
        and access_member.user_id = #{userId}
  )
order by v.version_no asc, v.version_id asc


  and r.project_id = #{projectId}
  and exists (
      select 1 from pm_project_member access_member
      where access_member.project_id = r.project_id
        and access_member.user_id = #{userId}
  )
order by r.create_time desc, r.requirement_id desc

select m.user_id as userId, u.user_name as userName, u.nick_name as nickName, u.email as email from pm_project_member m inner join sys_user u on u.user_id = m.user_id where m.project_id = #{projectId} and m.user_id in
#{userId}
order by m.user_id asc
